css:
body :where([data-bz-node="st"]) .bz-block{padding:0}
body :where([data-bz-node="st"]) .bz-container{padding:0;max-width:none}
body [data-bz-node="st"]>.bz-container{padding-inline:0}

body [data-bz-node="st"]{background:#fff;padding:70px 0 20px}
body [data-bz-node="st"]>.bz-container{max-width:var(--container)}
body [data-bz-node="st-grid"]{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:24px}
body [data-bz-node="st-grid"]>.bz-col{grid-column:auto}
body [data-bz-node^="st-tile-"]{display:flex;flex-direction:column;background:#2a2723;padding:34px 32px 36px;box-sizing:border-box}
body [data-bz-node^="st-value-"] h3{font:700 40px/1 var(--font-heading);letter-spacing:0;text-transform:uppercase;color:#fff;margin:0}
body [data-bz-node^="st-label-"]{margin-top:16px}
body [data-bz-node^="st-label-"] p{font:700 9.5px/1.7 var(--font-body);letter-spacing:.16em;text-transform:uppercase;color:rgba(255,255,255,.88);margin:0}
@media (max-width:1100px){body [data-bz-node="st"]{padding:48px 24px 10px}}
@media (max-width:640px){body [data-bz-node="st"]{padding:36px 20px 8px}body [data-bz-node="st-grid"]{gap:14px}body [data-bz-node^="st-value-"] h3{font-size:32px}}
